// Pure checker for one theme-guide memory lane. It does not certify the full browser contract.
const MIB=1024*1024,MAX_RSS=256*MIB,MAX_HEAP_GROWTH=4*MIB,MAX_RSS_GROWTH=32*MIB,MAX_GAP=200;
const finite=value=>typeof value==='number'&&Number.isFinite(value);
const integer=value=>Number.isSafeInteger(value);
const sorted=value=>[...value].sort();

function parsePS(raw){
  if(typeof raw!=='string')throw Error('raw_ps is not a string');
  const rows=[],lines=raw.split(/\r?\n/);
  for(const [index,line]of lines.entries()){
    if(!line.trim()){if(index===lines.length-1)continue;throw Error(`blank raw_ps line ${index+1}`);}
    const match=line.match(/^\s*(\d+)\s+(\d+)\s+(\d+)\s+((?:Sun|Mon|Tue|Wed|Thu|Fri|Sat)\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(?:0?[1-9]|[12]\d|3[01])\s+(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d\s+\d{4})\s+(.+?)\s*$/);
    if(!match)throw Error(`unparseable raw_ps line: ${line}`);
    rows.push({pid:Number(match[1]),ppid:Number(match[2]),rss_kib:Number(match[3]),start_identity:match[4].split(/\s+/).join(' '),command:match[5]});
  }
  return rows;
}

export function checkMemoryLane(lane,{browser,server,origin}={}){
  const errors=[];let maxRendererRSS=0,maxGap=0,heapGrowth=NaN,rssGrowth=NaN;
  const check=(condition,label)=>{if(!condition)errors.push(label);};
  const metric=(value,label,{int=false,positive=false}={})=>{check(finite(value)&&value>=0&&(!int||integer(value))&&(!positive||value>0),label);return finite(value)?value:0;};
  if(!lane||typeof lane!=='object')return{ok:false,errors:['missing lane'],max_renderer_rss_bytes:0,max_gap_ms:0,heap_growth_bytes:NaN,rss_growth_bytes:NaN,complete:false};
  check(lane.id!==undefined&&lane.id!==null,'lane id');
  check(Array.isArray(lane.errors)&&lane.errors.length===0,'lane errors');
  for(const [name,owner]of Object.entries({browser,server})){check(owner&&integer(owner.pid)&&owner.pid>0&&typeof owner.start_identity==='string'&&!!owner.start_identity,`${name} owner identity`);}
  let allowedOrigin;try{const parsed=new URL(origin);allowedOrigin=parsed.origin;check(origin===allowedOrigin,'memory origin');}catch{check(false,'memory origin');}
  const browserPID=browser?.pid,serverPID=server?.pid,samples=Array.isArray(lane.samples)?lane.samples:[];check(browserPID!==serverPID,'owner PID collision');check(Array.isArray(lane.samples)&&samples.length>0,'samples');
  const pidStarts=new Map(),sampleRendererRSS=[];
  for(const [index,sample]of samples.entries()){
    const p=`sample ${index}`;metric(sample?.started_ms,p+' started_ms');metric(sample?.completed_ms,p+' completed_ms');check(sample?.started_ms<=sample?.completed_ms,p+' time order');check(sample?.completed_ms-sample?.started_ms<=MAX_GAP,p+' acquisition duration');check(Array.isArray(sample?.errors)&&sample.errors.length===0,p+' errors');
    let parsed=[];try{parsed=parsePS(sample?.raw_ps);}catch(error){check(false,p+' '+error);}
    const rows=Array.isArray(sample?.rows)?sample.rows:[],ledger=rows.map(row=>({pid:row?.pid,ppid:row?.ppid,rss_kib:row?.rss_kib,start_identity:row?.start_identity,command:row?.command}));check(JSON.stringify(ledger)===JSON.stringify(parsed),p+' raw_ps/row ledger mismatch');
    const rowMap=new Map();for(const row of rows){const valid=row&&integer(row.pid)&&row.pid>0&&integer(row.ppid)&&row.ppid>=0&&integer(row.rss_kib)&&row.rss_kib>=0&&typeof row.start_identity==='string'&&!!row.start_identity&&typeof row.command==='string'&&!!row.command;check(valid,p+' invalid ps row');if(!valid)continue;check(!rowMap.has(row.pid),p+' duplicate ps PID');rowMap.set(row.pid,row);const prior=pidStarts.get(row.pid);check(prior===undefined||prior===row.start_identity,p+' reused PID');if(prior===undefined)pidStarts.set(row.pid,row.start_identity);}
    const info=Array.isArray(sample?.process_info)?sample.process_info:[],infoMap=new Map();for(const item of info){const valid=item&&integer(item.id)&&item.id>0&&typeof item.type==='string'&&!!item.type&&finite(item.cpuTime)&&item.cpuTime>=0;check(valid,p+' invalid process_info');if(!valid)continue;check(!infoMap.has(item.id),p+' duplicate SystemInfo PID');infoMap.set(item.id,item);check(rowMap.has(item.id),p+' SystemInfo PID missing ps row');}
    const browserInfo=info.filter(item=>item.id===browserPID&&item.type==='browser');check(browserInfo.length===1,p+' browser SystemInfo identity');check(!infoMap.has(serverPID),p+' server unexpectedly in SystemInfo');check(rowMap.get(browserPID)?.start_identity===browser?.start_identity,p+' browser ps identity');check(rowMap.get(serverPID)?.start_identity===server?.start_identity,p+' server ps identity');
    for(const row of rowMap.values()){if(row.pid===serverPID)continue;check(infoMap.has(row.pid),p+' unknown ps process');if(row.pid===browserPID)continue;const seen=new Set([row.pid]);let parent=row.ppid,owned=false;while(rowMap.has(parent)&&!seen.has(parent)){if(parent===browserPID){owned=true;break;}seen.add(parent);parent=rowMap.get(parent).ppid;}check(owned,p+' nonowned process');}
    let rendererRSS=0,renderers=0;for(const [pid,item]of infoMap){const row=rowMap.get(pid),flag=row?.command?.includes('--type=renderer')??false;if(item.type==='renderer'){renderers++;check(flag,p+' renderer command classification');rendererRSS+=(row?.rss_kib??0)*1024;}if(flag)check(item.type==='renderer',p+' misclassified renderer command');}check(renderers>0,p+' missing renderer');sampleRendererRSS[index]=rendererRSS;
  }
  for(let i=1;i<samples.length;i++)check(samples[i-1]?.completed_ms<=samples[i]?.completed_ms,`sample ${i} completion order`);
  const interval=(start,end,label)=>{metric(start,label+' start');metric(end,label+' end');check(start<=end,label+' order');const selected=samples.map((sample,index)=>({sample,index})).filter(x=>x.sample?.completed_ms>=start&&x.sample?.started_ms<=end);check(selected.length>0,label+' sample coverage');if(!selected.length)return;const edges=[Math.max(0,selected[0].sample.completed_ms-start),Math.max(0,end-selected.at(-1).sample.completed_ms),Math.max(0,selected.at(-1).sample.completed_ms-end)];for(let i=1;i<selected.length;i++)edges.push(selected[i].sample.completed_ms-selected[i-1].sample.completed_ms);for(const gap of edges){maxGap=Math.max(maxGap,gap);check(gap<=MAX_GAP,label+' sample gap');}};
  const cycles=Array.isArray(lane.cycles)?lane.cycles:[];check(cycles.length===20,'exactly 20 cycles');metric(lane.work_started_ms,'work started');metric(lane.work_completed_ms,'work completed');check(lane.work_started_ms<=lane.work_completed_ms,'work time order');let previous=lane.work_started_ms;for(let i=0;i<cycles.length;i++){const cycle=cycles[i];check(cycle?.index===i+1,`cycle ${i+1} index`);metric(cycle?.started_ms,`cycle ${i+1} start`);metric(cycle?.completed_ms,`cycle ${i+1} completion`);check(cycle?.started_ms>=previous&&cycle?.completed_ms>=cycle?.started_ms&&cycle?.completed_ms<=lane.work_completed_ms,`cycle ${i+1} time/order`);check(cycle?.ok===true,`cycle ${i+1} failed`);previous=cycle?.completed_ms;}check(!cycles.length||cycles[0].started_ms>=lane.work_started_ms,'cycle work start');interval(lane.work_started_ms,lane.work_completed_ms,'work');for(const [index,sample]of samples.entries())if(sample?.completed_ms>=lane.work_started_ms&&sample?.started_ms<=lane.work_completed_ms){const rss=sampleRendererRSS[index]??0;maxRendererRSS=Math.max(maxRendererRSS,rss);check(rss<=MAX_RSS,`sample ${index} renderer RSS budget`);}

  const endpoint=(value,label)=>{
    check(value&&typeof value==='object',label+' endpoint');if(!value||typeof value!=='object')return{heap:0,rss:0,topology:[]};metric(value.started_ms,label+' start');metric(value.completed_ms,label+' completion');check(value.started_ms<=value.completed_ms,label+' time order');const idle=value.idle??{};metric(idle.started_ms,label+' idle start');metric(idle.completed_ms,label+' idle completion');check(idle.started_ms>=value.started_ms&&idle.completed_ms-idle.started_ms>=5000&&idle.completed_ms<=value.completed_ms,label+' five second idle');check(integer(idle.network_before)&&idle.network_before>=0&&idle.network_before===idle.network_after,label+' idle network changed');
    const before=Array.isArray(idle.targets_before)?idle.targets_before:[],after=Array.isArray(idle.targets_after)?idle.targets_after:[];check(before.every(x=>typeof x==='string'&&!!x)&&after.every(x=>typeof x==='string'&&!!x)&&new Set(before).size===before.length&&new Set(after).size===after.length&&JSON.stringify(sorted(before))===JSON.stringify(sorted(after)),label+' idle targets changed');
    const targets=Array.isArray(value.targets)?value.targets:[],targetIDs=new Set(),sessions=new Set();check(targets.length===2&&targets.filter(x=>x?.type==='page').length===1&&targets.filter(x=>x?.type==='iframe').length===1,label+' guide topology');for(const target of targets){check(typeof target?.target_id==='string'&&!!target.target_id&&!targetIDs.has(target.target_id),label+' target identity');check(typeof target?.session_id==='string'&&!!target.session_id&&!sessions.has(target.session_id),label+' target session');check(typeof target?.url==='string'&&!!target.url&&typeof target?.isolate_id==='string'&&!!target.isolate_id,label+' target fields');try{const url=new URL(target.url),path=target.type==='page'?'/theme-lab':'/theme-lab/preview';check(url.origin===allowedOrigin&&url.pathname===path,label+' target origin/path/type');}catch{check(false,label+' target origin/path/type');}targetIDs.add(target?.target_id);sessions.add(target?.session_id);}check(JSON.stringify(sorted(before))===JSON.stringify(sorted(targetIDs)),label+' idle/endpoint target identity');
    const isolates=Array.isArray(value.isolates)?value.isolates:[],isolateIDs=new Set(),assigned=[];let heap=0;for(const isolate of isolates){check(typeof isolate?.id==='string'&&!!isolate.id&&!isolateIDs.has(isolate.id),label+' duplicate/invalid isolate');isolateIDs.add(isolate?.id);check(Array.isArray(isolate?.session_ids)&&isolate.session_ids.length>0&&new Set(isolate.session_ids).size===isolate.session_ids.length,label+' isolate sessions');assigned.push(...(isolate?.session_ids??[]));metric(isolate?.used_bytes,label+' isolate used');metric(isolate?.total_bytes,label+' isolate total');check(isolate?.used_bytes<=isolate?.total_bytes,label+' isolate heap order');check(isolate?.raw_heap&&isolate.raw_heap.usedSize===isolate.used_bytes&&isolate.raw_heap.totalSize===isolate.total_bytes,label+' raw heap binding');heap+=finite(isolate?.used_bytes)?isolate.used_bytes:0;}check(JSON.stringify(sorted(assigned))===JSON.stringify(sorted(sessions)),label+' isolate target coverage');for(const target of targets)check(isolateIDs.has(target.isolate_id)&&isolates.find(x=>x.id===target.isolate_id)?.session_ids?.includes(target.session_id),label+' target/isolate binding');
    const gc=Array.isArray(value.gc)?value.gc:[],gcIDs=new Set();check(gc.length===isolates.length,label+' GC count');for(const item of gc){check(typeof item?.isolate_id==='string'&&!gcIDs.has(item.isolate_id)&&isolateIDs.has(item.isolate_id),label+' GC isolate');gcIDs.add(item?.isolate_id);const isolate=isolates.find(x=>x.id===item?.isolate_id);check(isolate?.session_ids?.includes(item?.session_id),label+' GC canonical session');metric(item?.started_ms,label+' GC start');metric(item?.completed_ms,label+' GC completion');check(item?.started_ms>=value.started_ms&&item?.started_ms<=item?.completed_ms&&item?.completed_ms<=idle.started_ms&&item?.ok===true,label+' GC result/order');}
    const dom=Array.isArray(value.dom)?value.dom:[],domSessions=new Set();check(dom.length===sessions.size,label+' DOM target count');for(const item of dom){check(typeof item?.session_id==='string'&&sessions.has(item.session_id)&&!domSessions.has(item.session_id),label+' DOM session');domSessions.add(item?.session_id);for(const key of ['documents','nodes','jsEventListeners'])metric(item?.[key],label+' DOM '+key,{int:true});}
    check(integer(value.sample_index)&&value.sample_index>=0&&value.sample_index<samples.length,label+' endpoint sample index');const sample=samples[value.sample_index];check(sample?.completed_ms>=idle.completed_ms&&Math.abs((sample?.completed_ms??Infinity)-value.completed_ms)<=MAX_GAP,label+' endpoint sample timing');return{heap,rss:sampleRendererRSS[value.sample_index]??0,topology:targets.map(x=>`${x.type}\0${x.url}`).sort()};
  };
  const baseline=endpoint(lane.baseline,'baseline'),final=endpoint(lane.final,'final');check(JSON.stringify(baseline.topology)===JSON.stringify(final.topology),'baseline/final topology changed');if(lane.baseline&&lane.final){check(lane.baseline.completed_ms<=lane.work_started_ms&&lane.work_completed_ms<=lane.final.started_ms,'endpoint/work order');interval(lane.baseline.started_ms,lane.final.completed_ms,'full acquisition');}
  heapGrowth=final.heap-baseline.heap;rssGrowth=final.rss-baseline.rss;check(finite(heapGrowth)&&heapGrowth<=MAX_HEAP_GROWTH,'retained heap growth budget');check(finite(rssGrowth)&&rssGrowth<=MAX_RSS_GROWTH,'retained renderer RSS growth budget');
  return{ok:errors.length===0,errors,max_renderer_rss_bytes:maxRendererRSS,max_gap_ms:maxGap,heap_growth_bytes:heapGrowth,rss_growth_bytes:rssGrowth,complete:false};
}

export {parsePS};
